example.code:
// Create a client with default options (spawns CLI server)
await using var client = new CopilotClient();

// Create a session
await using var session = await client.CreateSessionAsync(new() { OnPermissionRequest = PermissionHandler.ApproveAll, Model = "gpt-5.4" });

// Handle events
using var subscription = session.On<SessionEvent>(evt =>
{
    if (evt is AssistantMessageEvent assistantMessage)
        Console.WriteLine(assistantMessage.Data?.Content);
});

// Send a message
await session.SendAsync(new MessageOptions { Prompt = "Hello!" });

// Default options - spawns the bundled runtime using stdio
var client = new CopilotClient();

// Connect to an existing runtime
var client = new CopilotClient(new CopilotClientOptions { Connection = RuntimeConnection.ForUri("localhost:3000") });

// Custom runtime path with specific log level
var client = new CopilotClient(new CopilotClientOptions
{
    Connection = RuntimeConnection.ForStdio(path: "/usr/local/bin/copilot"),
    LogLevel = CopilotLogLevel.Debug
});

var client = new CopilotClient();
await client.StartAsync();
// Now ready to create sessions

// If normal stop hangs, force stop
var stopTask = client.StopAsync();
if (!stopTask.Wait(TimeSpan.FromSeconds(5)))
{
    await client.ForceStopAsync();
}

member.summary:
Resolves  /
 for the wire payload,
validating empty-mode requirements.

example.code:
// Basic session
var session = await client.CreateSessionAsync(new() { OnPermissionRequest = PermissionHandler.ApproveAll });

// Session with model and tools
var session = await client.CreateSessionAsync(new()
{
    OnPermissionRequest = PermissionHandler.ApproveAll,
    Model = "gpt-5.4",
    Tools = [AIFunctionFactory.Create(MyToolMethod)]
});

// Resume a previous session
var session = await client.ResumeSessionAsync("session-123", new() { OnPermissionRequest = PermissionHandler.ApproveAll });

// Resume with new tools
var session = await client.ResumeSessionAsync("session-123", new()
{
    OnPermissionRequest = PermissionHandler.ApproveAll,
    Tools = [AIFunctionFactory.Create(MyNewToolMethod)]
});

var lastId = await client.GetLastSessionIdAsync();
if (lastId != null)
{
    var session = await client.ResumeSessionAsync(lastId, new() { OnPermissionRequest = PermissionHandler.ApproveAll });
}

var sessions = await client.ListSessionsAsync();
foreach (var session in sessions)
{
    Console.WriteLine($"{session.SessionId}: {session.Summary}");
}

var metadata = await client.GetSessionMetadataAsync("session-123");
if (metadata != null)
{
    Console.WriteLine($"Session started at: {metadata.StartTime}");
}

var sessionId = await client.GetForegroundSessionIdAsync();
if (sessionId != null)
{
    Console.WriteLine($"TUI is displaying session: {sessionId}");
}

using var sub = client.OnLifecycle<SessionForegroundEvent>(evt =>
{
    Console.WriteLine($"Session {evt.SessionId} is now in foreground");
});

member.summary:
Gets which traffic the callbacks serve.  (the default) or
 serves only requests made for sessions this client creates or resumes;
 also serves the runtime's shared background traffic.

example.code:
await using var session = await client.CreateSessionAsync(new() { OnPermissionRequest = PermissionHandler.ApproveAll, Model = "gpt-5.4" });

// Subscribe to events
using var subscription = session.On<SessionEvent>(evt =>
{
    if (evt is AssistantMessageEvent assistantMessage)
    {
        Console.WriteLine($"Assistant: {assistantMessage.Data?.Content}");
    }
});

// Send a message and wait for completion
await session.SendAndWaitAsync(new MessageOptions { Prompt = "Hello, world!" });

var messageId = await session.SendAsync(new MessageOptions
{
    Prompt = "Explain this code",
    Attachments = new List<Attachment>
    {
        new AttachmentFile { Path = "./Program.cs", DisplayName = "Program.cs" }
    }
});

// Send and wait for completion with default 60s timeout
var response = await session.SendAndWaitAsync(new MessageOptions { Prompt = "What is 2+2?" });
Console.WriteLine(response?.Data?.Content); // "4"

using var subscription = session.On<SessionEvent>(evt =>
{
    switch (evt)
    {
        case AssistantMessageEvent:
            Console.WriteLine($"Assistant: {evt.Data?.Content}");
            break;
        case SessionErrorEvent:
            Console.WriteLine($"Error: {evt.Data?.Message}");
            break;
    }
});

// Or filter to a specific event kind at compile time:
using var sub2 = session.On<AssistantMessageEvent>(evt =>
    Console.WriteLine(evt.Data?.Content));

// The handler is automatically unsubscribed when the subscription is disposed.

var events = await session.GetEventsAsync();
foreach (var evt in events)
{
    if (evt is AssistantMessageEvent)
    {
        Console.WriteLine($"Assistant: {evt.Data?.Content}");
    }
}

// Start a long-running request
var messageTask = session.SendAsync(new MessageOptions
{
    Prompt = "Write a very long story..."
});

// Abort after 5 seconds
await Task.Delay(TimeSpan.FromSeconds(5));
await session.AbortAsync();

await session.SetModelAsync("gpt-5.4");
await session.SetModelAsync("claude-sonnet-4.6", "high");
await session.SetModelAsync("gpt-5.4", new SetModelOptions { ContextTier = ContextTier.LongContext });

await session.LogAsync("Build completed successfully");
await session.LogAsync("Disk space low", level: SessionLogLevel.Warning);
await session.LogAsync("Connection failed", level: SessionLogLevel.Error);
await session.LogAsync("Temporary status", ephemeral: true);

// Using 'await using' for automatic disposal — session can still be resumed later
await using var session = await client.CreateSessionAsync(new() { OnPermissionRequest = PermissionHandler.ApproveAll });

// Or manually dispose
var session2 = await client.CreateSessionAsync(new() { OnPermissionRequest = PermissionHandler.ApproveAll });
// ... use the session ...
await session2.DisposeAsync();

var session = await client.CreateSessionAsync(new SessionConfig
{
    AvailableTools = new ToolSet()
        .AddBuiltIn(BuiltInTools.Isolated)
        .AddMcp("*")
        .AddCustom("*"),
});

member.summary:
Handler called after a tool execution whose result was a failure.
 only fires for successful tool executions;
register this handler in addition to observe failed tool calls.

Sandbox configuration applied when the session is constructed, before MCP servers start.
Same shape as the sandboxConfig option of session options update;
an identical later update is a no-op.

Whether to repair a damaged transcript on resume. Defaults to true in
all modes. Set false to reject recovery. Recovery can discard a torn tail;
inspect  after resume.
